function Button({ children, icon: Icon, variant = '', onClick }) { return <button className={`button ${variant}`} onClick={onClick}>{Icon && <Icon size={16} />}{children}</button>; }
function IconButton({ icon: Icon, label, onClick }) { return <button className="icon-button" aria-label={label} title={label} onClick={onClick}><Icon size={17} /></button>; }
function Pill({ children, tone = 'neutral' }) { return <span className={`pill ${tone}`}><i />{children}</span>; }
function Heading({ eyebrow, title, description, actions }) { return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div><div className="heading-actions">{actions}</div></div>; }
function EmptyState({ title = 'No results found', text = 'Try adjusting your search or filters.' }) { return <div className="empty-state"><Search size={21} /><b>{title}</b><span>{text}</span></div>; }
function MapCanvas({ compact = false, onSelect }) {
  const [zoom, setZoom] = useState(1);
  const cities = [['Seattle', 176, 278], ['Portland', 330, 201], ['Sacramento', 499, 180], ['San Francisco', 446, 157], ['Boise', 662, 119], ['Spokane', 596, 239]];
  return <div className={`map-canvas ${compact ? 'compact' : ''}`}><div className="map-grid" /><svg style={{ transform: `scale(${zoom})` }} viewBox="0 0 820 390" preserveAspectRatio="none" aria-label="Regional fleet map"><path className="water" d="M0 270C90 252 120 286 190 248C250 215 280 240 322 211V390H0Z"/><path className="park" d="M455 14C510 38 492 78 552 83C600 88 609 115 576 145C541 177 559 207 623 201C691 195 685 230 647 255C615 277 676 307 717 294L820 282V0Z"/><path className="road major" d="M54 352C160 323 190 277 266 284C365 293 397 222 476 220C570 217 620 155 778 143"/><path className="road" d="M111 37C174 93 206 93 274 133C329 165 349 205 395 241C439 276 477 313 501 374M22 126C131 141 164 168 214 186C283 211 303 220 352 272C400 324 451 344 544 350M317 8C298 74 306 104 341 144C376 183 405 201 468 193C535 186 589 197 655 236C713 272 762 266 814 239"/><path className="minor" d="M5 201C94 209 138 193 192 211M203 15C201 58 226 71 269 83M390 16C425 55 461 69 490 98M569 26C551 76 585 105 640 115M44 296C97 287 133 301 156 333M686 325C663 290 678 268 741 252"/><path className="map-route" d="M176 278C237 264 266 217 330 201S450 229 499 180S600 156 662 119"/><path className="map-route alt" d="M330 201C343 153 392 141 446 157S536 203 596 239"/>{cities.map(([name, x, y], i) => <g key={name} className="map-marker" onClick={onSelect} onKeyDown={event => (event.key === 'Enter' || event.key === ' ') && onSelect?.()} tabIndex="0" role="button" aria-label={`${name} map marker`}><circle className="halo" cx={x} cy={y} r={i === 1 ? 14 : 11}/><circle className="core" cx={x} cy={y} r="5"/><text x={x + 12} y={y - 9}>{name}</text></g>)}{[[261,231],[379,195],[540,164],[614,137],[390,175]].map(([x,y],i)=><g className="truck-marker" key={i} transform={`translate(${x} ${y})`}><circle r="10"/><path d="M-4-3h5v6h-5zM1-1h3l2 2v2H1z"/></g>)}</svg><span className="ocean-label">PACIFIC OCEAN</span><div className="map-controls"><button aria-label="Zoom in" onClick={()=>setZoom(value=>Math.min(1.35,value+.1))}>+</button><button aria-label="Zoom out" onClick={()=>setZoom(value=>Math.max(.85,value-.1))}>−</button><button aria-label="Center map" onClick={()=>setZoom(1)}><Navigation size={14}/></button></div><small className="map-credit">Map data © LogiCraft Operations</small></div>;
}
function KPI({ label, value, delta, icon: Icon, tone = 'blue', down = false, note = 'vs last month' }) { return <article className="kpi"><div className="kpi-top"><span>{label}</span><i className={`kpi-icon ${tone}`}><Icon size={17}/></i></div><b className="kpi-value">{value}</b><div className="kpi-foot"><span className={down ? 'delta down' : 'delta'}>{down ? <ArrowDownRight size={13}/> : <ArrowUpRight size={13}/>} {delta}</span><small>{note}</small></div></article>; }
function TableToolbar({ value, setValue, filters, setFilter, action }) { return <div className="table-toolbar"><label className="table-search"><Search size={16}/><input placeholder="Search anything..." value={value} onChange={e => setValue(e.target.value)}/></label>{filters && <select aria-label="Filter by status" onChange={e => setFilter(e.target.value)}><option value="All">All statuses</option>{filters.map(f=><option key={f}>{f}</option>)}</select>}{action}</div>; }

